python3 - <<'EOF'
p='src/services/auth-service.js'
s=open(p).read()
s=s.replace("import { query } from '../db.js';\n", "import { query } from '../db.js';\nimport { UserRepository } from '../repositories/user-repository.js';\n\nconst users = new UserRepository();\n",1)
s+="""
// Promise-based, unlike the callback functions above. UserRepository.findByEmail
// already skips soft-deleted users and resolves to null when there is no match.
export function findUserForLogin(email) {
  return users.findByEmail(email);
}
"""
open(p,'w').write(s)
p='tests/auth-service.test.js'
s=open(p).read()
s=s.replace("import { findByEmail, isActive } from '../src/services/auth-service.js';",
"import { findByEmail, isActive, findUserForLogin } from '../src/services/auth-service.js';\nimport { update } from '../src/db.js';\n\nconst setDeleted = (table, id, when) => new Promise((resolve, reject) =>\n  update(table, id, { deleted_at: when }, (err, row) => (err ? reject(err) : resolve(row))));")
s+="""
test('findUserForLogin returns the active user with that email', async () => {
  const user = await findUserForLogin('ada@example.com');
  assert.equal(user.id, 1);
  assert.equal(user.deleted_at, null);
});

test('findUserForLogin returns null for an unknown or soft-deleted email', async () => {
  assert.equal(await findUserForLogin('nobody@example.com'), null);
  assert.equal(await findUserForLogin('alan@example.com'), null);
});

test('findUserForLogin stops returning a user once they are soft-deleted', async (t) => {
  t.after(() => setDeleted('users', 2, null));
  assert.equal((await findUserForLogin('grace@example.com')).id, 2);
  await setDeleted('users', 2, '2026-10-22');
  assert.equal(await findUserForLogin('grace@example.com'), null);
});
"""
open(p,'w').write(s)
EOF
npm test 2>&1 | grep -E "^ℹ (tests|pass|fail)|✖"; npm run lint 2>&1 | tail -1; node scripts/check-routes.js | tail -1; git status --short

